+import { log } from "../log";
+
+export async function recordView(pageId: string): Promise<void> {
+  try {
+    await fetch(`/metrics/views/${pageId}`, { method: "POST" });
+  } catch (err) {
+    log.warn("metrics: view not recorded", { pageId, err });
+  }
+}

