+import { log } from "../log";
+
+export async function recordScroll(pageId: string, depth: number): Promise<void> {
+  try {
+    await fetch(`/metrics/scroll/${pageId}`, {
+      method: "POST",
+      body: JSON.stringify({ depth }),
+    });
+  } catch (err) {
+    log.warn("metrics: scroll not recorded", { pageId, depth, err });
+  }
+}
